actions.script:
// a client contact cancels a request it raised, and makes no other move (ironstone.client.ClientServices, impl-projects.md P10b)
if (!!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) {
    if (toStatusId !== 'ReqCancelled') { ec.message.addError(ec.l10n.localize('Only the team moves a request on')); return }
    const out = ec.service.sync().name('ironstone.client.ClientServices.cancel#ClientRequest').parameters({requestId: requestId}).call()
    if (!ec.message.hasError()) ec.message.addMessage(out.message, 'success')
    return
}
let triager = false
if (appRoot === 'Projects') {
    const access = ec.service.sync().name('ironstone.projects.ProjectRequestServices.get#ProjectRequestAccess').parameters({requestId: requestId, need: 'check'}).call() || {}
    triager = !!access.canTriage && access.request?.statusId !== 'ReqDraft'
}
const out = triager
    ? ec.service.sync().name('ironstone.projects.ProjectRequestServices.triage#Request').parameters({requestId: requestId, action: 'status', value: toStatusId}).call()
    : ec.service.sync().name('ironstone.commons.RequestServices.set#RequestStatus').parameters({requestId: requestId, toStatusId: toStatusId}).call()
if (!ec.message.hasError()) ec.message.addMessage(out.message, 'success')

service-call.in-map:
{requestId:requestId, requestName:requestName,
                    requestTypeEnumId:requestTypeEnumId, priority:(priority || null), customerPartyId:(customerPartyId || null), description:description,
                    responseRequiredDate:(responseRequiredDate || null)}

{requestId:requestId, requestName:requestName,
                    requestTypeEnumId:requestTypeEnumId, priority:priority, customerPartyId:(customerPartyId || null), rootWorkEffortId:(rootWorkEffortId || null),
                    assigneePartyId:(assigneePartyId || null), responseRequiredDate:(responseRequiredDate ?? ''), description:(description ?? '')}

actions.script:
projects = appRoot === 'Projects'
// a client contact (the PROJECT_CLIENT permission; impl-projects.md P10b): its part of the request only
clientView = !!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')
detailPath = projects ? '/qapps/Projects/Requests/RequestDetail' : '/qapps/Commons/Requests/RequestDetail'
// Manufacturing (impl-manufacturing P11): a maintenance request of the user's plants, on the Commons request
mfgRequest = appRoot === 'Manufacturing'
productionRequest = {}
if (mfgRequest) detailPath = '/qapps/Manufacturing/WorkCenters/RequestDetail'
// Warehouse (impl-warehouse P15): a stock request in its own section (template/WarehouseRequestDetail.xml)
if (appRoot === 'Warehouse') {
    let wh = {}
    try {
        const service = 'ironstone.warehouse.TransferServices.get#StockRequestDetail'
        wh = ec.service.sync().name(service).parameters({requestId: requestId}).call() || {}
    } catch (error) {
        ec.logger.warn('Warehouse stock request ' + requestId + ': ' + error.message)
    }
    stockRequestFound = !!wh.requestFound && !ec.message.hasError()
    ec.message.clearErrors()
    stockRequest = wh.stockRequest || {}
    stockItemRows = wh.itemRows || []
    fromFacilities = wh.fromFacilities || []
    recordFound = false
    return
}
let pd = {}
if (projects) {
    const out = ec.service.sync().name('ironstone.projects.ProjectRequestServices.get#ProjectRequestDetail').parameters({requestId: requestId}).call() || {}
    recordFound = !!out.visible
    pd = out.detail || {}
    detail = pd.base || {}
} else {
    detail = ec.service.sync().name('ironstone.commons.RequestServices.get#RequestDetail').parameters({requestId: requestId}).call() || {}
    recordFound = !!detail.visible
}
if (mfgRequest && recordFound) {
    ec.message.pushErrors()
    try {
        productionRequest = ec.service.sync().name('ironstone.manufacturing.DowntimeServices.get#RequestContext')
                .parameters({requestId: requestId}).call() || {}
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    recordFound = !!productionRequest.available
}
const tabKeys = projects ? ['overview', 'conversation', 'work'].concat(pd.itemsShown ? ['items'] : []).concat(['files'])
        : ['overview', 'conversation', 'tasks', 'files']
tab = tabKeys.includes(tab) ? tab : 'overview'
if (!recordFound) return
const L = (text) => ec.l10n.localize(text)
const enc = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
request = detail.request
canSubmit = !!detail.canSubmit
canCancel = !!detail.canCancel
canEdit = !!detail.canEdit
canReassign = !!detail.canReassign
canAddTask = !!detail.canAddTask
canLink = !!detail.canLink
linkedRecordList = (detail.linkedRecordList || []).map((record) => Object.assign({}, record, {cardHtml: '<m-record-card record-entity="' + enc(record.recordEntityName)
        + '" record-id="' + enc(record.recordId) + '" card-url="/apps/' + (projects ? 'Projects' : 'Commons') + '/Chatter/recordCard" dense></m-record-card>'}))
// the status-bar: the stages and the moves the user may make
stageStatusIds = projects ? (pd.stageStatusIds || []) : (detail.stageStatusIds || [])
allowedStatusIds = projects ? (pd.allowedStatusIds || []) : (detail.allowedStatusIds || [])
// a client contact opens no contact (Commons is not its): the people without links
partyList = (detail.partyList || []).map((one) => clientView ? Object.assign({}, one, {url: null}) : one)
taskList = detail.taskList || []
// in Manufacturing a follow-up task opens its WorkItemDetail there, and a run or operation its work order (F38)
if (mfgRequest) {
    const productionIds = productionRequest.productionWorkIds || []
    const workUrls = Object.fromEntries((productionRequest.workRows || []).map((row) => [row.workEffortId, row.url]))
    taskList = taskList.map((task) => Object.assign({}, task, {url: productionIds.includes(task.workEffortId) ? workUrls[task.workEffortId]
            : '/qapps/Manufacturing/WorkCenters/WorkItemDetail?workEffortId=' + encodeURIComponent(task.workEffortId)}))
}
captionText = [L('Request') + ' ' + requestId, request.typeLabel, request.filedByName ? L('raised by') + ' ' + request.filedByName : null,
    request.requestDateText].filter((part) => part).join(' · ')
const fact = (label, value, cls) => '<div class="col-auto"><div class="text-caption m-muted">' + enc(L(label)) + '</div><div class="text-body2' + (cls ? ' ' + cls : '') + '">' + value + '</div></div>'
const person = (name, userId) => name ? '<span class="row inline items-center no-wrap"><m-avatar name="' + enc(name) + '"'
        + (userId ? ' user-id="' + enc(userId) + '"' : '') + ' size="22px" class="q-mr-xs"></m-avatar>' + enc(name) + '</span>' : '—'
const link = (text, url) => '<a href="' + enc(url) + '" @click.prevent="$root.setUrl(\'' + enc(url) + '\')">' + enc(text) + '</a>'
if (projects) {
    canTriage = !!pd.canTriage
    canConvert = !!pd.canConvert
    isOpen = !!pd.open
    workList = pd.workList || []
    itemList = pd.itemList || []
    noteList = pd.noteList || []
    projectName = pd.projectName || ''
    workText = workList.length ? pd.workDoneCount + '/' + workList.length + ' ' + L('done') : ''
    const projectUrl = request.rootWorkEffortId ? '/qapps/Projects/Projects/ProjectDetail/Requests?workEffortId=' + encodeURIComponent(request.rootWorkEffortId) : null
    factsHtml = '<div class="row q-col-gutter-lg m-request-facts">'
        + fact('Customer', person(request.customerName, request.customerUserId), '')
        + fact('Project', projectUrl ? link(projectName, projectUrl) : enc(L('None yet')), projectUrl ? '' : 'm-muted')
        + fact('Priority', enc(request.priorityText || '—'), '')
        + fact('Due', enc(request.responseRequiredText ? String(request.responseRequiredText).replace(/ \d{1,2}:\d{2} [AP]M$/, '') : '—'), '')
        + fact('Assignee', request.assigneeName ? person(request.assigneeName, request.assigneeUserId) : enc(L('Unassigned')), request.assigneeName ? '' : 'text-warning')
        + fact('Filed by', enc(request.filedByName || '—'), '')
        + fact('Date', enc(request.requestDateText || '—'), '')
        + fact('Channel', enc(pd.channelLabel || ''), '')
        + (workList.length ? fact('Work', enc(workText), '') : '')
        + '</div>'
    typeChipHtml = request.typeLabel ? '<q-chip dense square class="q-my-none q-ml-none q-mr-sm m-tonal text-grey-8" icon="sym_o_category">' + enc(request.typeLabel) + '</q-chip>' : ''
    chatterTab = pd.customerOutside && isOpen ? 'message' : 'log'
    // the values of the dialogs
    requestEdit = {requestId: requestId, tab: tab, requestName: request.requestName || '', requestTypeEnumId: request.requestTypeEnumId || '',
        priority: request.priority != null ? String(request.priority) : '5', customerPartyId: request.customerPartyId || '',
        rootWorkEffortId: request.rootWorkEffortId || '', assigneePartyId: request.assigneePartyId || '',
        responseRequiredDate: request.responseRequiredEdit ? request.responseRequiredEdit.substring(0, 10) : '', description: request.description || ''}
    customerName = request.customerName || ''
    assigneeName = request.assigneeName || ''
    projectOptions = ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || []
    if (request.rootWorkEffortId && !projectOptions.some((option) => option.key === request.rootWorkEffortId))
        projectOptions = [{key: request.rootWorkEffortId, text: projectName + ' (' + request.rootWorkEffortId + ')'}].concat(projectOptions)
    makeProjectId = request.rootWorkEffortId || (projectOptions[0]?.key || '')
    makeTypes = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').parameters({rootWorkEffortId: makeProjectId || null}).call()?.offeredList || [])
    makeTypeId = ({RqtBugFix: 'WepFix', RqtNewFeature: 'WepNewFeature'}[request.requestTypeEnumId]) || 'WepTask'
    if (!makeTypes.some((type) => type.enumId === makeTypeId)) makeTypes = [{enumId: makeTypeId, label: L(makeTypeId === 'WepFix' ? 'Bug Fix' : makeTypeId === 'WepNewFeature' ? 'New Feature' : 'Task')}].concat(makeTypes)
    makeValues = {requestId: requestId, rootWorkEffortId: makeProjectId, workEffortName: request.requestName || '', purposeEnumId: makeTypeId,
        priority: request.priority != null ? String(request.priority) : '5', estimatedCompletionDate: requestEdit.responseRequiredDate, description: request.description || ''}
    const suggested = String(request.requestName || '').toUpperCase().replace(/[^A-Z0-9 ]/g, '').split(/\s+/).filter((word) => word).map((word) => word[0]).join('').substring(0, 6)
    convertValues = {requestId: requestId, newProjectName: request.requestName || '', newProjectId: suggested.length >= 2 ? suggested : ''}
}
factsCommonsHtml = '<div class="row q-col-gutter-lg m-request-facts">'
    + fact('Priority', enc(request.priorityText || '—'), '')
    + fact('Customer', person(request.customerName, request.customerUserId), '')
    + fact('Assigned', person(request.assigneeName, request.assigneeUserId), '')
    + (request.responseRequiredText ? fact('Response wanted by', enc(request.responseRequiredText), '') : '')
    + fact('Updated', enc(request.updatedText || '—'), '')
    + '</div>'
if (!projects) factsHtml = factsCommonsHtml
const tabs = projects ? [['overview', 'Overview'], ['conversation', 'Conversation'], ['work', 'Work' + (workList.length ? ' (' + workList.length + ')' : '')]]
        .concat(pd.itemsShown ? [['items', 'Items' + (itemList.length ? ' (' + itemList.length + ')' : '')]] : []).concat([['files', 'Files']])
    : [['overview', 'Overview'], ['conversation', 'Conversation'], ['tasks', 'Tasks' + (taskList.length ? ' (' + taskList.length + ')' : '')], ['files', 'Files']]
const base = detailPath + '?requestId=' + encodeURIComponent(requestId)
tabsHtml = '<q-tabs dense no-caps inline-label narrow-indicator outside-arrows mobile-arrows align="left" active-color="primary" indicator-color="primary"'
        + ' class="text-grey-8 m-request-tabs" model-value="' + enc(tab) + '">' + tabs.map(([key, label]) => {
            // the conversation is beside the overview from 1440 px, a tab below
            const cls = key === 'conversation' && tab !== 'conversation' ? ' class="lt-lg"' : ''
            return '<q-tab name="' + key + '" label="' + enc(L(label)) + '"' + cls + ' data-tab="' + key + '" @click="$root.setUrl(\'' + enc(base + '&tab=' + key) + '\')"></q-tab>'
        }).join('') + '</q-tabs><q-separator class="q-mb-sm"></q-separator>'
// the tabs in the terminal: links to this screen with the tab
tabsTui = {t: 'row', id: 'RequestTabs', c: tabs.map(([key, label]) => ({t: 'link', id: 'RequestTab_' + key, text: key === tab ? '[' + L(label) + ']' : L(label),
    url: sri.buildUrl('.').path + base.substring(base.indexOf('?')) + '&tab=' + key}))}
filesUrl = base + '&tab=files'
if (!projects) {
    requestEdit = {requestId: requestId, requestName: request.requestName, requestTypeEnumId: request.requestTypeEnumId,
        priority: request.priority != null ? String(request.priority) : '5', customerPartyId: request.customerPartyId,
        description: request.description, responseRequiredDate: request.responseRequiredEdit ? request.responseRequiredEdit.substring(0, 10) : ''}
    customerName = request.customerName || ''
}
